280	    fn token_stream_with_finish(
281	        n: usize,
282	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
283	        use paigasus_helikon_core::FinishReason;
284	        let mut events: Vec<Result<ModelEvent, ModelError>> = (0..n)
285	            .map(|i| {
286	                Ok(ModelEvent::TokenDelta {
287	                    text: format!("chunk-{i}"),
288	                })
289	            })
290	            .collect();
291	        events.push(Ok(ModelEvent::Finish {
292	            reason: FinishReason::Stop,
293	        }));
294	        futures_util::stream::iter(events)
295	    }
