321	        let cancelled = Arc::new(AtomicBool::new(false));
322	        let cancelled_clone = cancelled.clone();
323	
324	        let source = async_stream::stream! {
325	            yield Ok::<ModelEvent, ModelError>(ModelEvent::TokenDelta { text: "first".to_owned() });
326	            // Signal cancellation after the first token.
327	            if !cancelled_clone.swap(true, Ordering::SeqCst) {
