242	        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
243	        let caps = m.capabilities();
244	        assert!(caps.streaming);
245	        assert!(caps.tools);
246	        assert!(caps.structured_output);
247	        assert!(
248	            !caps.vision,
249	            "vision not advertised (no image-block mapping)"
250	        );
251	    }
