1	//! Map Amazon Bedrock SDK errors to [`paigasus_helikon_core::ModelError`].
2	//!
3	//! Per ADR-10 (*No silent auto-retry inside the loop*), the runner never
4	//! retries — retries are an application-layer concern via `RetryingModel`.
5	//!
6	//! The `classify` function is a pure, unit-testable classifier that operates
7	//! on string error codes and optional HTTP status codes, mirroring the style
8	//! of the Anthropic provider's `map_error_type`. `map_sdk_error` wraps it
9	//! by extracting the code/status from the real [`SdkError`] variants.
10	
11	use aws_smithy_runtime_api::client::result::SdkError;
12	use aws_smithy_runtime_api::http::Headers;
13	use aws_smithy_types::error::metadata::ProvideErrorMetadata;
14	use paigasus_helikon_core::ModelError;
15	
16	/// Classify a Bedrock error into a [`ModelError`] from raw components.
17	///
18	/// This function is intentionally pure so it can be unit-tested without
19	/// constructing live `SdkError` values.
20	///
21	/// | `code`                       | Result                             |
22	/// |------------------------------|------------------------------------|
23	/// | `ThrottlingException`        | `RateLimited { retry_after_ms }`   |
24	/// | `ServiceUnavailableException`, `ModelNotReadyException`, `InternalServerException`, `ModelStreamErrorException`, `ModelTimeoutException` | `Unavailable` |
25	/// | `AccessDeniedException`      | `Refused { reason: message }`      |
26	/// | `ValidationException` + message contains "too long"/"maximum context" | `ContextLengthExceeded` |
27	/// | `ValidationException` (other)| `Other`                            |
28	/// | unknown / `None`             | `Other`                            |
29	pub(crate) fn classify(
30	    code: Option<&str>,
31	    _status: Option<u16>,
32	    message: &str,
33	    retry_after_ms: Option<u64>,
34	) -> ModelError {
35	    match code {
36	        Some("ThrottlingException") => ModelError::RateLimited { retry_after_ms },
37	        Some(
38	            "ServiceUnavailableException"
39	            | "ModelNotReadyException"
40	            | "InternalServerException"
41	            | "ModelStreamErrorException"
42	            | "ModelTimeoutException",
43	        ) => ModelError::Unavailable,
44	        Some("AccessDeniedException") => ModelError::Refused {
45	            reason: message.to_owned(),
46	        },
47	        Some("ValidationException") => {
48	            let msg_lower = message.to_ascii_lowercase();
49	            if msg_lower.contains("too long") || msg_lower.contains("maximum context") {
50	                ModelError::ContextLengthExceeded
51	            } else {
52	                ModelError::Other(anyhow::anyhow!("bedrock ValidationException: {message}"))
53	            }
54	        }
55	        _ => ModelError::Other(anyhow::anyhow!(
56	            "bedrock error {}: {message}",
57	            code.unwrap_or("unknown")
58	        )),
59	    }
60	}
61	
62	/// Parse the `Retry-After` header (integer seconds) from Bedrock response headers into milliseconds.
63	///
64	/// Returns `None` when the header is absent or its value is not a non-negative integer
65	/// (HTTP-date retry-after values are not supported — `None` is the safe fallback).
66	pub(crate) fn parse_retry_after_ms(headers: &Headers) -> Option<u64> {
67	    headers
68	        .get("retry-after")
69	        .and_then(|v| v.trim().parse::<u64>().ok())
70	        .map(|seconds| seconds.saturating_mul(1000))
71	}
72	
73	/// Map a Bedrock SDK [`SdkError`] to a [`ModelError`].
74	///
75	/// For `ServiceError`, the modeled error code and message are extracted via
76	/// [`ProvideErrorMetadata`] and delegated to [`classify`]. Transport-level
77	/// failures (`DispatchFailure`, `TimeoutError`, `ConstructionFailure`,
78	/// `ResponseError`) map to [`ModelError::Transport`].
79	///
80	/// This generic variant does **not** inspect HTTP headers (the response type `R`
81	/// may not be an HTTP response — e.g. the event-stream `recv()` path produces
82	/// `SdkError<_, RawMessage>`). Call [`map_sdk_http_error`] when `R` is known to
83	/// be [`aws_smithy_runtime_api::http::Response`] and you want `Retry-After`
84	/// header extraction.
85	pub(crate) fn map_sdk_error<E, R>(err: SdkError<E, R>) -> ModelError
86	where
87	    E: ProvideErrorMetadata + std::fmt::Debug,
88	    R: std::fmt::Debug,
89	{
90	    match &err {
91	        SdkError::ServiceError(svc) => {
92	            let code = svc.err().code();
93	            let message = svc.err().message().unwrap_or("");
94	            classify(code, None, message, None)
95	        }
96	        SdkError::DispatchFailure(_)
97	        | SdkError::TimeoutError(_)
98	        | SdkError::ConstructionFailure(_)
99	        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
100	        // Non-exhaustive: treat any future variant as transport.
101	        _ => ModelError::Transport(format!("{err:?}")),
102	    }
103	}
104	
105	/// Map a Bedrock SDK [`SdkError`] whose response type is the concrete HTTP
106	/// response to a [`ModelError`], extracting `Retry-After` header and HTTP
107	/// status from the raw response.
108	///
109	/// This is the preferred variant for the initial `fluent.send()` call on a
110	/// Bedrock operation, where the SDK returns
111	/// `SdkError<E, aws_smithy_runtime_api::client::orchestrator::HttpResponse>`.
112	pub(crate) fn map_sdk_http_error<E>(
113	    err: SdkError<E, aws_smithy_runtime_api::http::Response>,
114	) -> ModelError
115	where
116	    E: ProvideErrorMetadata + std::fmt::Debug,
117	{
118	    match &err {
119	        SdkError::ServiceError(svc) => {
120	            let code = svc.err().code();
121	            let message = svc.err().message().unwrap_or("");
122	            let raw = svc.raw();
123	            let status = Some(raw.status().as_u16());
124	            let retry_after_ms = parse_retry_after_ms(raw.headers());
125	            classify(code, status, message, retry_after_ms)
126	        }
127	        SdkError::DispatchFailure(_)
128	        | SdkError::TimeoutError(_)
129	        | SdkError::ConstructionFailure(_)
130	        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
131	        // Non-exhaustive: treat any future variant as transport.
132	        _ => ModelError::Transport(format!("{err:?}")),
133	    }
134	}
