218	// ── BedrockModel constructors (here because they construct a builder) ─────────
219	
220	impl crate::BedrockModel {
221	    /// Start building a Bedrock model for the given model id.
222	    ///
223	    /// ```ignore
224	    /// use paigasus_helikon_providers_bedrock::BedrockModel;
225	    /// # async fn f() -> Result<(), Box<dyn std::error::Error>> {
226	    /// let model = BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0")
227	    ///     .sdk_config(&aws_config::defaults(aws_config::BehaviorVersion::v2026_11_17())
228	    ///         .load().await)
229	    ///     .build()?;
230	    /// # Ok(()) }
231	    /// ```
232	    pub fn converse(model_id: impl Into<String>) -> BedrockModelBuilder {
233	        BedrockModelBuilder::new(model_id)
234	    }
235	
236	    /// Construct a [`crate::BedrockModel`] by loading AWS configuration from
237	    /// the environment (credential files, environment variables, IMDS, SSO…).
238	    ///
239	    /// ## Credential laziness
240	    ///
241	    /// The AWS credential chain is **lazy** — loading the config does not prove
242	    /// that your credentials will be accepted by Bedrock.  Auth/permission
243	    /// failures surface at invoke time as a
244	    /// [`paigasus_helikon_core::ModelError`].
245	    ///
246	    /// ## BehaviorVersion
247	    ///
248	    /// Uses the pinned `BehaviorVersion::v2026_11_17()` so that a Dependabot
249	    /// `aws-config` bump cannot silently shift SDK behavior. This version
250	    /// applies the AWS SDK retry behavior from the Retry Behavior 2.1 spec.
251	    /// It also applies a default read timeout to AWS SDK clients.
252	    ///
253	    /// ## Region
254	    ///
255	    /// Pass `None` to use the region from the environment
256	    /// (`AWS_DEFAULT_REGION`, `~/.aws/config`, …).  Pass `Some(region)` to
257	    /// override it.
258	    pub async fn from_env(model_id: impl Into<String>) -> Result<Self, BuildError> {
259	        Self::from_env_with_region(model_id, None::<Region>).await
260	    }
261	
262	    /// Like [`from_env`][Self::from_env] but with an explicit region override.
263	    pub async fn from_env_with_region(
264	        model_id: impl Into<String>,
265	        region: Option<impl Into<Region>>,
266	    ) -> Result<Self, BuildError> {
267	        let mut loader = aws_config::defaults(aws_config::BehaviorVersion::v2026_11_17());
268	        if let Some(r) = region {
269	            loader = loader.region(r.into());
270	        }
271	        let sdk_cfg = loader.load().await;
272	        BedrockModelBuilder::new(model_id)
273	            .sdk_config(&sdk_cfg)
274	            .build()
275	    }
276	}
