1	//! [`BedrockModelBuilder`] — fluent constructor for [`crate::BedrockModel`].
2	//!
3	//! ## Credentials / AWS config laziness
4	//!
5	//! The synchronous [`BedrockModelBuilder::build`] only validates the model-id
6	//! and assembles a Bedrock SDK [`Client`]; it **does not** make any network
7	//! call and **does not** verify your AWS credentials.  Credential/auth
8	//! failures surface later, at invoke time, as a
9	//! [`paigasus_helikon_core::ModelError`].
10	//!
11	//! [`BedrockModel::from_env`] loads the SDK config from the environment (an
12	//! `async` operation because it may fetch IMDS/SSO tokens), but the same
13	//! credential-laziness rule applies: loading the config does not prove the
14	//! credentials will be accepted by Bedrock.
15	
16	use std::sync::Arc;
17	
18	use aws_config::Region;
19	use aws_sdk_bedrockruntime::Client;
20	use paigasus_helikon_core::ModelCapabilities;
21	
22	use crate::capabilities::caps_for;
23	use crate::family::ModelFamily;
24	
25	// ── BuildError ────────────────────────────────────────────────────────────────
26	
27	/// Errors that can occur while building a [`crate::BedrockModel`].
28	///
29	/// Runtime errors (auth failures, throttling, …) are reported through
30	/// [`paigasus_helikon_core::ModelError`] at invoke time, not here.
31	#[derive(Debug, thiserror::Error)]
32	#[non_exhaustive]
33	pub enum BuildError {
34	    /// No AWS SDK client or `SdkConfig` was supplied and `from_env` was not
35	    /// used.  Call `.client(…)`, `.sdk_config(…)`, or use
36	    /// [`crate::BedrockModel::from_env`].
37	    #[error("no AWS client or SdkConfig provided")]
38	    MissingClient,
39	
40	    /// The model identifier was empty.  Pass a non-empty Bedrock model id such
41	    /// as `"anthropic.claude-3-5-sonnet-20241022-v2:0"`.
42	    #[error("model id is empty")]
43	    EmptyModelId,
44	}
45	
46	// ── Config ────────────────────────────────────────────────────────────────────
47	
48	/// Resolved builder configuration held by [`crate::BedrockModel`].
49	///
50	/// Cheaply clonable via `Arc` — the `BedrockModel` holds `Arc<Config>` so
51	/// that clone + move into the `'static` stream is zero-copy.
52	#[derive(Debug, Clone)]
53	pub(crate) struct Config {
54	    /// Initialized Bedrock SDK client (region already baked in).
55	    pub(crate) client: Client,
56	    /// Bedrock model identifier (e.g. `anthropic.claude-3-5-sonnet-20241022-v2:0`).
57	    pub(crate) model_id: String,
58	    /// Detected model family used for capability routing.
59	    pub(crate) family: ModelFamily,
60	    /// Resolved capability flags for this model instance.
61	    pub(crate) capabilities: ModelCapabilities,
62	    /// Optional default for `max_tokens` when the caller does not set it.
63	    ///
64	    /// When `None` (the default), `inferenceConfig.maxTokens` is omitted from
65	    /// the Bedrock request so that each model applies its own correct limit.
66	    /// Set via [`BedrockModelBuilder::max_output_tokens_default`].
67	    pub(crate) max_output_default: Option<u32>,
68	}
69	
70	// ── BedrockModelBuilder ───────────────────────────────────────────────────────
71	
72	/// Fluent builder for [`crate::BedrockModel`].
73	///
74	/// Start with [`crate::BedrockModel::converse`].
75	///
76	/// ## Credential laziness
77	///
78	/// `build()` is **synchronous** and **does not** contact any AWS endpoint.
79	/// Credential resolution happens inside the SDK client at the first
80	/// invoke call.
81	pub struct BedrockModelBuilder {
82	    model_id: String,
83	    /// Caller-supplied, fully-initialized client (highest precedence).
84	    client: Option<Client>,
85	    /// Caller-supplied `SdkConfig` (used to construct a client when no direct
86	    /// client is injected).
87	    sdk_config: Option<aws_config::SdkConfig>,
88	    /// Optional region override; ignored if a client was injected directly.
89	    region: Option<Region>,
90	    /// Optional capabilities override (wins over the `caps_for` lookup).
91	    capabilities_override: Option<ModelCapabilities>,
92	    /// Optional `max_output_tokens` override.
93	    max_output_override: Option<u32>,
94	}
95	
96	impl BedrockModelBuilder {
97	    pub(crate) fn new(model_id: impl Into<String>) -> Self {
98	        Self {
99	            model_id: model_id.into(),
100	            client: None,
101	            sdk_config: None,
102	            region: None,
103	            capabilities_override: None,
104	            max_output_override: None,
105	        }
106	    }
107	
108	    /// Inject a pre-constructed Bedrock SDK client.
109	    ///
110	    /// This takes highest precedence.  When a client is injected any
111	    /// `.region(…)` call is **ignored** (the client already has a region baked
112	    /// in) and `.sdk_config(…)` is not used to construct the client either.
113	    pub fn client(mut self, c: Client) -> Self {
114	        self.client = Some(c);
115	        self
116	    }
117	
118	    /// Build the SDK client from a caller-provided [`aws_config::SdkConfig`].
119	    ///
120	    /// Ignored if a direct client was already injected via `.client(…)`.
121	    pub fn sdk_config(mut self, c: &aws_config::SdkConfig) -> Self {
122	        self.sdk_config = Some(c.clone());
123	        self
124	    }
125	
126	    /// Override the AWS region.
127	    ///
128	    /// **Note:** this setting is **ignored** when a client is injected via
129	    /// `.client(…)` because the client already has its region baked in.  The
130	    /// region is only applied when building a client from `.sdk_config(…)` or
131	    /// when using [`crate::BedrockModel::from_env`].
132	    pub fn region(mut self, r: impl Into<Region>) -> Self {
133	        self.region = Some(r.into());
134	        self
135	    }
136	
137	    /// Override the capability flags for this model instance.
138	    ///
139	    /// Wins over the built-in `caps_for` lookup table.
140	    pub fn capabilities(mut self, c: ModelCapabilities) -> Self {
141	        self.capabilities_override = Some(c);
142	        self
143	    }
144	
145	    /// Override the default `max_output_tokens` passed to Bedrock when the
146	    /// caller does not set `ModelSettings::max_output_tokens`.
147	    pub fn max_output_tokens_default(mut self, n: u32) -> Self {
148	        self.max_output_override = Some(n);
149	        self
150	    }
151	
152	    /// Resolve all settings and construct the [`crate::BedrockModel`].
153	    ///
154	    /// This is **synchronous** — no network calls are made.
155	    ///
156	    /// # Errors
157	    ///
158	    /// - [`BuildError::EmptyModelId`] — model id is an empty string.
159	    /// - [`BuildError::MissingClient`] — neither `.client(…)` nor
160	    ///   `.sdk_config(…)` was called (use [`crate::BedrockModel::from_env`] for
161	    ///   automatic env-based client construction).
162	    pub fn build(self) -> Result<crate::BedrockModel, BuildError> {
163	        // 1. Validate model id.
164	        if self.model_id.is_empty() {
165	            return Err(BuildError::EmptyModelId);
166	        }
167	
168	        // 2. Resolve client.
169	        let client = if let Some(c) = self.client {
170	            // Injected client wins; region override is ignored.
171	            if self.region.is_some() {
172	                tracing::debug!(
173	                    target: "paigasus::bedrock::builder",
174	                    "region() was set but a Client was injected — region override ignored; \
175	                     the injected client's region takes precedence",
176	                );
177	            }
178	            c
179	        } else if let Some(ref sdk_cfg) = self.sdk_config {
180	            if let Some(region) = self.region {
181	                // Region override: build a per-client config that layers the
182	                // override on top of the caller's SdkConfig, then construct
183	                // the client from that config.
184	                let client_cfg = aws_sdk_bedrockruntime::config::Builder::from(sdk_cfg)
185	                    .region(region)
186	                    .build();
187	                aws_sdk_bedrockruntime::Client::from_conf(client_cfg)
188	            } else {
189	                Client::new(sdk_cfg)
190	            }
191	        } else {
192	            return Err(BuildError::MissingClient);
193	        };
194	
195	        // 3. Detect family and resolve capabilities.
196	        let family = ModelFamily::from_model_id(&self.model_id);
197	        if family == ModelFamily::Unknown {
198	            tracing::debug!(
199	                target: "paigasus::bedrock::builder",
200	                model_id = %self.model_id,
201	                "model family not detected from the model id; structured-output synthesis and forced tool choice are off",
202	            );
203	        }
204	        let default_caps = caps_for(family);
205	        let capabilities = self.capabilities_override.unwrap_or(default_caps);
206	        let max_output_default = self.max_output_override;
207	
208	        Ok(crate::BedrockModel(Arc::new(Config {
209	            client,
210	            model_id: self.model_id,
211	            family,
212	            capabilities,
213	            max_output_default,
214	        })))
215	    }
216	}
