1	//! `StreamTranslator` — Bedrock `ConverseStreamOutput` events → `ModelEvent`.
2	//!
3	//! ## Usage / Finish ordering
4	//!
5	//! The Bedrock Converse API emits events in this order:
6	//!
7	//! ```text
8	//! MessageStart
9	//! ContentBlockStart | ContentBlockDelta | ContentBlockStop  (interleaved)
10	//! MessageStop         ← stop_reason lives here
11	//! Metadata            ← usage lives here (AFTER MessageStop)
12	//! ```
13	//!
14	//! Per the `paigasus_helikon_core::Model::invoke` ordering contract,
15	//! `ModelEvent::Finish` is terminal and `ModelEvent::Usage` may appear
16	//! anywhere in the stream — most providers emit one immediately before
17	//! `Finish`. Because Bedrock emits `Metadata` (where usage lives) **after**
18	//! `MessageStop` (where the stop reason lives), this translator buffers the
19	//! stop reason when `MessageStop` arrives and emits nothing until `Metadata`
20	//! arrives — at that point it emits `Usage` immediately followed by `Finish`.
21	//!
22	//! If (contrary to the typical wire order) `Metadata` arrives **before**
23	//! `MessageStop`, `Usage` is emitted immediately on `Metadata` and `Finish`
24	//! is emitted immediately on `MessageStop`, which also satisfies the contract.
25	
26	use std::collections::HashMap;
27	
28	use aws_sdk_bedrockruntime::types::{
29	    ContentBlockDelta, ContentBlockStart, ConverseStreamOutput, ReasoningContentBlockDelta,
30	    StopReason,
31	};
32	use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};
33	
34	use crate::translate::tools::SYNTHESIZED_TOOL_NAME;
35	
36	// ── internal block state ──────────────────────────────────────────────────────
37	
38	/// Per-content-block state keyed by `content_block_index`.
39	///
40	/// Reasoning content blocks are identified purely by the
41	/// `ContentBlockDelta::ReasoningContent` delta variant; no separate block-state
42	/// entry is needed for them.
43	#[derive(Debug)]
44	enum BlockState {
45	    Text,
46	    ToolUse {
47	        call_id: String,
48	        name: String,
49	        /// `true` after the first `ToolCallDelta` has been emitted (name
50	        /// appears only in that first delta; subsequent deltas set it to
51	        /// `None`).
52	        name_emitted: bool,
53	    },
54	}
55	
56	// ── public translator ─────────────────────────────────────────────────────────
57	
58	/// State machine that maps Bedrock `ConverseStreamOutput` events to
59	/// `paigasus_helikon_core::ModelEvent`s.
60	///
61	/// Call [`StreamTranslator::consume`] once per SDK event.  The translator is
62	/// pure (no I/O) and is intended to be driven from an `async_stream!` wrapper
63	/// that feeds it chunks from `converse_stream`.
64	///
65	/// ## Synthesizing mode
66	///
67	/// When `synthesizing = true` the model was asked to fill a JSON schema via a
68	/// forced-tool call (`__paigasus_structured_output__`).  In that mode the
69	/// synthesized tool's input deltas are re-emitted as `TokenDelta`s and the
70	/// terminal `tool_use` stop reason is rewritten to `Stop`.  If a *real* tool
71	/// fires alongside the synthesized one, `ModelError::Other` is returned
72	/// (protocol violation).
73	#[derive(Debug, Default)]
74	pub struct StreamTranslator {
75	    /// `content_block_index` → per-block state.
76	    blocks: HashMap<i32, BlockState>,
77	    /// Whether we are in structured-output synthesis mode.
78	    synthesizing: bool,
79	    /// The content-block index of the synthesized tool's block (if any).
80	    synthesized_block_index: Option<i32>,
81	    /// `true` if at least one *real* (non-synthesized) tool block started.
82	    real_tool_fired: bool,
83	    /// Buffered stop reason from `MessageStop`; held until `Metadata` arrives
84	    /// so that `Usage` can be emitted first.
85	    pending_stop_reason: Option<StopReason>,
86	    /// `true` once a `Metadata` event has been processed.
87	    metadata_seen: bool,
88	}
89	
90	impl StreamTranslator {
91	    /// Create a new translator.
92	    ///
93	    /// Set `synthesizing` to `true` when the request was built with
94	    /// structured-output synthesis (forced `__paigasus_structured_output__`
95	    /// tool call).
96	    pub fn new(synthesizing: bool) -> Self {
97	        Self {
98	            synthesizing,
99	            ..Default::default()
100	        }
101	    }
102	
103	    /// Consume one `ConverseStreamOutput` event and return zero or more
104	    /// `ModelEvent`s (or `ModelError`s) produced by it.
105	    pub fn consume(&mut self, ev: ConverseStreamOutput) -> Vec<Result<ModelEvent, ModelError>> {
106	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
107	
108	        match ev {
109	            // ── events that produce no output ─────────────────────────────────
110	            ConverseStreamOutput::MessageStart(_) => {}
111	            ConverseStreamOutput::ContentBlockStop(_) => {}
112	
113	            // ── content block start ───────────────────────────────────────────
114	            ConverseStreamOutput::ContentBlockStart(e) => {
115	                let idx = e.content_block_index();
116	                match e.start() {
117	                    Some(ContentBlockStart::ToolUse(tu)) => {
118	                        let call_id = tu.tool_use_id().to_owned();
119	                        let name = tu.name().to_owned();
120	
121	                        if self.synthesizing && name == SYNTHESIZED_TOOL_NAME {
122	                            self.synthesized_block_index = Some(idx);
123	                        } else {
124	                            self.real_tool_fired = true;
125	                            // Emit the name-carrying delta immediately on block
126	                            // start (mirrors the Anthropic provider's behaviour
127	                            // of emitting name on the first input-json delta).
128	                            // We *don't* emit here — we wait for the first
129	                            // tool-input delta so the call_id→state map is
130	                            // consistent.
131	                        }
132	                        self.blocks.insert(
133	                            idx,
134	                            BlockState::ToolUse {
135	                                call_id,
136	                                name,
137	                                name_emitted: false,
138	                            },
139	                        );
140	                    }
141	                    Some(ContentBlockStart::Image(_) | ContentBlockStart::ToolResult(_)) => {
142	                        // Not a tool we translate; record nothing.
143	                    }
144	                    Some(_) | None => {
145	                        // Text or unknown start: record as text block.
146	                        self.blocks.insert(idx, BlockState::Text);
147	                    }
148	                }
149	            }
150	
151	            // ── content block delta ───────────────────────────────────────────
152	            ConverseStreamOutput::ContentBlockDelta(e) => {
153	                let idx = e.content_block_index();
154	                match e.delta() {
155	                    Some(ContentBlockDelta::Text(text)) => {
156	                        out.push(Ok(ModelEvent::TokenDelta { text: text.clone() }));
157	                    }
158	                    Some(ContentBlockDelta::ToolUse(tu_delta)) => {
159	                        let input = tu_delta.input().to_owned();
160	                        let is_synth = Some(idx) == self.synthesized_block_index;
161	
162	                        if is_synth {
163	                            // Remap synthesized tool input to TokenDelta.
164	                            out.push(Ok(ModelEvent::TokenDelta { text: input }));
165	                        } else if let Some(BlockState::ToolUse {
166	                            call_id,
167	                            name,
168	                            name_emitted,
169	                        }) = self.blocks.get_mut(&idx)
170	                        {
171	                            let emit_name = if *name_emitted {
172	                                None
173	                            } else {
174	                                *name_emitted = true;
175	                                Some(name.clone())
176	                            };
177	                            out.push(Ok(ModelEvent::ToolCallDelta {
178	                                call_id: call_id.clone(),
179	                                name: emit_name,
180	                                args_delta: input,
181	                            }));
182	                        }
183	                        // If no block state (shouldn't happen for well-formed
184	                        // streams), silently drop rather than panic.
185	                    }
186	                    Some(ContentBlockDelta::ReasoningContent(rc)) => match rc {
187	                        ReasoningContentBlockDelta::Text(text) => {
188	                            out.push(Ok(ModelEvent::ReasoningDelta { text: text.clone() }));
189	                        }
190	                        ReasoningContentBlockDelta::Signature(_) => {
191	                            // Signature is a round-trip token for multi-turn
192	                            // extended-thinking; we drop it here (not yet
193	                            // plumbed through the session layer).
194	                            tracing::debug!(
195	                                target: "paigasus::bedrock::stream",
196	                                "reasoning signature delta dropped (round-trip not yet supported)",
197	                            );
198	                        }
199	                        ReasoningContentBlockDelta::RedactedContent(_) => {
200	                            // Encrypted reasoning blob — provider-opaque, drop.
201	                            tracing::debug!(
202	                                target: "paigasus::bedrock::stream",
203	                                "reasoning redacted-content delta dropped",
204	                            );
205	                        }
206	                        _ => {
207	                            // Forward-compat: ignore unknown reasoning variants.
208	                        }
209	                    },
210	                    // Image, ToolResult, Citation, Unknown deltas — drop.
211	                    Some(_) | None => {}
212	                }
213	            }
214	
215	            // ── message stop (stop_reason) ────────────────────────────────────
216	            ConverseStreamOutput::MessageStop(e) => {
217	                let stop_reason = e.stop_reason().clone();
218	                if self.metadata_seen {
219	                    // Metadata already arrived; emit Finish now.
220	                    out.extend(self.finish_events(stop_reason));
221	                } else {
222	                    // Buffer; Metadata will trigger Usage + Finish.
223	                    self.pending_stop_reason = Some(stop_reason);
224	                }
225	            }
226	
227	            // ── metadata (usage) ──────────────────────────────────────────────
228	            ConverseStreamOutput::Metadata(e) => {
229	                self.metadata_seen = true;
230	                if let Some(usage) = e.usage() {
231	                    out.push(Ok(ModelEvent::Usage {
232	                        input_tokens: usage.input_tokens().max(0) as u32,
233	                        output_tokens: usage.output_tokens().max(0) as u32,
234	                        cached_input_tokens: usage
235	                            .cache_read_input_tokens()
236	                            .map(|n| n.max(0) as u32),
237	                        reasoning_tokens: None,
238	                    }));
239	                }
240	                // If a buffered stop reason is waiting, emit Finish now.
241	                if let Some(reason) = self.pending_stop_reason.take() {
242	                    out.extend(self.finish_events(reason));
243	                }
244	            }
245	
246	            // Forward-compat catch-all: Unknown and any future enum variants
247	            // added by the SDK are silently ignored.
248	            _ => {}
249	        }
250	
251	        out
252	    }
253	
254	    /// Flush any buffered stop reason when the Bedrock stream ends normally
255	    /// (EOF) without having emitted a `Metadata` event.
256	    ///
257	    /// Returns the terminal `Finish` event (or a `ModelError::Other` for the
258	    /// both-tools-fired error condition) if a stop reason is still pending,
259	    /// or `None` if the stream already emitted its terminal event through the
260	    /// normal `Metadata`→`Finish` path.
261	    ///
262	    /// **Call this only on the EOF path, not on the cancellation path.**
263	    /// Cancellation must end the stream without emitting `Finish`.
264	    pub(crate) fn finish(&mut self) -> Option<Result<ModelEvent, ModelError>> {
265	        self.pending_stop_reason
266	            .take()
267	            .map(|reason| self.finish_events(reason).remove(0))
268	    }
269	
270	    // ── private helpers ───────────────────────────────────────────────────────
271	
272	    /// Translate a `StopReason` into the terminal event(s).
273	    ///
274	    /// Returns a single `Ok(Finish{..})` in normal cases, or a single
275	    /// `Err(ModelError::Other)` when both a real and the synthesized tool
276	    /// fired in synthesis mode.
277	    fn finish_events(&self, reason: StopReason) -> Vec<Result<ModelEvent, ModelError>> {
278	        let finish = match reason {
279	            StopReason::EndTurn | StopReason::StopSequence => Ok(ModelEvent::Finish {
280	                reason: FinishReason::Stop,
281	            }),
282	            StopReason::ToolUse => {
283	                if self.synthesizing {
284	                    if self.real_tool_fired {
285	                        // Both tools fired — protocol violation.
286	                        Err(ModelError::Other(anyhow::anyhow!(
287	                            "bedrock stream: structured-output synthesis: \
288	                             model fired both a real tool and the synthesized \
289	                             output tool '__paigasus_structured_output__'"
290	                        )))
291	                    } else {
292	                        // Only synthesized tool fired — rewrite to Stop.
293	                        Ok(ModelEvent::Finish {
294	                            reason: FinishReason::Stop,
295	                        })
296	                    }
297	                } else {
298	                    Ok(ModelEvent::Finish {
299	                        reason: FinishReason::ToolCalls,
300	                    })
301	                }
302	            }
303	            StopReason::MaxTokens => Ok(ModelEvent::Finish {
304	                reason: FinishReason::Length,
305	            }),
306	            StopReason::GuardrailIntervened | StopReason::ContentFiltered => {
307	                Ok(ModelEvent::Finish {
308	                    reason: FinishReason::ContentFilter,
309	                })
310	            }
311	            other => Ok(ModelEvent::Finish {
312	                reason: FinishReason::Other(other.as_str().to_owned()),
313	            }),
314	        };
315	        vec![finish]
316	    }
317	}
