740	        let has_error = out.iter().any(|r| matches!(r, Err(ModelError::Other(_))));
741	        assert!(
742	            has_error,
743	            "expected Err(Other) for both-tools-fired; got {out:?}"
744	        );
745	    }
746	
747	    // NOTE: ConverseStreamOutput::Unknown is #[non_exhaustive] and cannot be
748	    // constructed outside the AWS SDK crate, so it cannot be exercised by a test
749	    // here; the translator handles it via the match's catch-all arm (no output).
750	
751	    /// MessageStart → no events emitted.
752	    #[test]
753	    fn message_start_produces_no_events() {
754	        let out = run(false, vec![message_start()]);
755	        assert!(out.is_empty());
756	    }
757	
758	    /// ContentBlockStop → no events emitted.
759	    #[test]
760	    fn content_block_stop_produces_no_events() {
761	        let out = run(false, vec![content_block_stop(0)]);
762	        assert!(out.is_empty());
763	    }
764	
765	    // ── finish() flush tests (Fix 3) ──────────────────────────────────────────
766	
767	    /// `MessageStop(EndTurn)` with NO subsequent `Metadata` event:
768	    /// `finish()` must yield `Finish(Stop)` — the consumer must see the
769	    /// terminal event even when Bedrock closes the stream without metadata.
770	    #[test]
771	    fn finish_flushes_pending_stop_reason_without_metadata() {
772	        let mut t = StreamTranslator::new(false);
773	
774	        // Feed only MessageStop — no Metadata.
775	        let out = t.consume(message_stop(StopReason::EndTurn));
776	        assert!(
777	            out.is_empty(),
778	            "MessageStop alone must buffer, not emit immediately"
779	        );
780	
781	        // EOF path: call finish() and expect the terminal Finish(Stop).
782	        let terminal = t
783	            .finish()
784	            .expect("finish() must return Some when stop reason is buffered");
785	        assert!(
786	            matches!(terminal, Ok(ModelEvent::Finish { ref reason }) if *reason == FinishReason::Stop),
787	            "expected Finish(Stop), got {terminal:?}"
788	        );
789	
790	        // A second call must return None (idempotent drain).
791	        assert!(
792	            t.finish().is_none(),
793	            "finish() must return None after the pending reason was drained"
794	        );
795	    }
796	
797	    /// When the normal `Metadata`→`Finish` path has already fired,
798	    /// `finish()` must return `None` (nothing left to flush).
799	    #[test]
800	    fn finish_returns_none_after_normal_metadata_path() {
801	        let mut t = StreamTranslator::new(false);
802	        t.consume(message_stop(StopReason::EndTurn));
803	        // Metadata arrives — translator drains pending_stop_reason internally.
804	        let out = t.consume(metadata(10, 5, None));
805	        // out should contain Usage + Finish.
806	        assert_eq!(out.len(), 2);
807	
808	        // finish() must now return None — nothing is pending.
809	        assert!(
810	            t.finish().is_none(),
811	            "finish() must return None when Metadata already drained the pending reason"
812	        );
813	    }
814	
815	    /// `finish()` on the both-tools-fired error path (synthesizing mode):
816	    /// must surface `ModelError::Other` rather than `Finish`.
817	    #[test]
818	    fn finish_surfaces_both_tools_error_without_metadata() {
819	        let mut t = StreamTranslator::new(true);
820	        // Both synthesized and real tool fire.
821	        t.consume(tool_use_start(0, "tu_synth", SYNTHESIZED_TOOL_NAME));
822	        t.consume(tool_use_start(1, "tu_real", "search"));
823	        // MessageStop with ToolUse — but no Metadata follows.
824	        let out = t.consume(message_stop(StopReason::ToolUse));
825	        assert!(out.is_empty(), "MessageStop alone must buffer");
826	
827	        let terminal = t.finish().expect("finish() must return Some");
828	        assert!(
829	            matches!(terminal, Err(ModelError::Other(_))),
830	            "expected Err(Other) for both-tools-fired; got {terminal:?}"
831	        );
832	    }
833	}
