22	/// A fully-assembled Bedrock Converse request, ready to send.
23	///
24	/// The fields map onto the Bedrock SDK `converse` / `converse_stream` input
25	/// parameters. Callers should inspect `synthesizing` to decide how to route
26	/// stream events (synthesized structured output → `TokenDelta` remapping).
27	#[derive(Debug)]
28	pub(crate) struct PreparedConverse {
29	    /// Bedrock model identifier (may include cross-region profile prefix).
30	    pub(crate) model_id: String,
31	    /// System prompt blocks.
32	    pub(crate) system: Vec<SystemContentBlock>,
33	    /// Conversation turns. Adjacent same-role turns are joined.
34	    pub(crate) messages: Vec<Message>,
35	    /// Tool configuration (tools list + optional tool_choice).
36	    pub(crate) tool_config: Option<ToolConfiguration>,
37	    /// Base inference parameters.
38	    pub(crate) inference_config: Option<InferenceConfiguration>,
39	    /// Whether the stream translator should remap the synthesized tool's
40	    /// output to `TokenDelta`.
41	    pub(crate) synthesizing: bool,
42	}
