1	//! `ResponseFormat` → synthesized forced-tool + tool_choice for Bedrock Converse.
2	//!
3	//! When the model family supports forced tool choice, `JsonSchema` / `JsonObject`
4	//! response formats are synthesized into a hidden tool named [`SYNTHESIZED_TOOL_NAME`]
5	//! with a matching `toolChoice: {tool: {name}}` that forces the model to call it.
6	//! Families that do NOT support forced tool choice (e.g. Llama, Titan) return
7	//! `synthesizing: false`; the caller degrades to plain text.
8	
9	use aws_sdk_bedrockruntime::types::{
10	    SpecificToolChoice, ToolChoice as BedrockToolChoice, ToolInputSchema, ToolSpecification,
11	};
12	use paigasus_helikon_core::{ModelError, ResponseFormat};
13	
14	use crate::document::value_to_document;
15	use crate::family::ModelFamily;
16	use crate::translate::schema::{rewrite_tool_schema, Ruleset};
17	use crate::translate::tools::SYNTHESIZED_TOOL_NAME;
18	
19	/// Outcome of [`synthesize`].
20	pub(crate) struct Synthesized {
21	    /// Synthesized tool to append to the tool list (if any).
22	    pub(crate) tool: Option<ToolSpecification>,
23	    /// `toolChoice` to include in `ToolConfiguration` (if any).
24	    pub(crate) tool_choice: Option<BedrockToolChoice>,
25	    /// `true` when the stream translator should remap the synthesized tool's
26	    /// output to a `TokenDelta`.
27	    pub(crate) synthesizing: bool,
28	}
29	
30	/// Build the synthesized tool + `toolChoice` for the given response format.
31	///
32	/// Returns `synthesizing: false` for:
33	/// - `ResponseFormat::Text` / `None` (no synthesis needed),
34	/// - any format on a family that does not support forced tool choice (degrades
35	///   to text).
36	///
37	/// # Errors
38	/// Currently infallible (reserved-name and conflict guards are in `mod.rs`
39	/// where `tool_choice` is also available).
40	pub(crate) fn synthesize(
41	    rf: Option<&ResponseFormat>,
42	    family: ModelFamily,
43	    ruleset: Ruleset,
44	) -> Result<Synthesized, ModelError> {
45	    let no_synthesis = Ok(Synthesized {
46	        tool: None,
47	        tool_choice: None,
48	        synthesizing: false,
49	    });
50	
51	    match rf {
52	        Some(ResponseFormat::JsonSchema { name, schema, .. }) => {
53	            if !family.supports_forced_tool_choice() {
54	                tracing::debug!(
55	                    target: "paigasus::bedrock::translate",
56	                    family = ?family,
57	                    "ResponseFormat::JsonSchema not synthesized — family does not support \
58	                     forced tool choice; degrading to Text",
59	                );
60	                return no_synthesis;
61	            }
62	            let rewritten = rewrite_tool_schema(schema, ruleset);
63	            let doc = value_to_document(&rewritten);
64	            let spec = ToolSpecification::builder()
65	                .name(SYNTHESIZED_TOOL_NAME)
66	                .description(format!("Return data matching the {name} schema."))
67	                .input_schema(ToolInputSchema::Json(doc))
68	                .build()
69	                .map_err(|e| {
70	                    ModelError::Other(anyhow::anyhow!("failed to build synthesized tool: {e}"))
71	                })?;
72	            let tc = build_specific_tool_choice(SYNTHESIZED_TOOL_NAME)?;
73	            Ok(Synthesized {
74	                tool: Some(spec),
75	                tool_choice: Some(tc),
76	                synthesizing: true,
77	            })
78	        }
79	
80	        Some(ResponseFormat::JsonObject) => {
81	            if !family.supports_forced_tool_choice() {
82	                tracing::debug!(
83	                    target: "paigasus::bedrock::translate",
84	                    family = ?family,
85	                    "ResponseFormat::JsonObject not synthesized — family does not support \
86	                     forced tool choice; degrading to Text",
87	                );
88	                return no_synthesis;
89	            }
90	            let schema = serde_json::json!({"type": "object"});
91	            let rewritten = rewrite_tool_schema(&schema, ruleset);
92	            let doc = value_to_document(&rewritten);
93	            let spec = ToolSpecification::builder()
94	                .name(SYNTHESIZED_TOOL_NAME)
95	                .description("Return a JSON object.")
96	                .input_schema(ToolInputSchema::Json(doc))
97	                .build()
98	                .map_err(|e| {
99	                    ModelError::Other(anyhow::anyhow!("failed to build synthesized tool: {e}"))
100	                })?;
101	            let tc = build_specific_tool_choice(SYNTHESIZED_TOOL_NAME)?;
102	            Ok(Synthesized {
103	                tool: Some(spec),
104	                tool_choice: Some(tc),
105	                synthesizing: true,
106	            })
107	        }
108	
109	        _ => no_synthesis,
110	    }
111	}
112	
113	fn build_specific_tool_choice(name: &str) -> Result<BedrockToolChoice, ModelError> {
114	    let specific = SpecificToolChoice::builder()
115	        .name(name)
116	        .build()
117	        .map_err(|e| {
118	            ModelError::Other(anyhow::anyhow!("failed to build SpecificToolChoice: {e}"))
119	        })?;
120	    Ok(BedrockToolChoice::Tool(specific))
121	}
122	
123	// ── Unit tests ────────────────────────────────────────────────────────────────
124	
125	#[cfg(test)]
126	mod tests {
127	    use super::*;
128	    use paigasus_helikon_core::ResponseFormat;
129	    use serde_json::json;
130	
131	    fn strict_ruleset() -> Ruleset {
132	        Ruleset::for_family(ModelFamily::Anthropic)
133	    }
134	
135	    #[test]
136	    fn text_format_returns_no_synthesis() {
137	        let s = synthesize(
138	            Some(&ResponseFormat::Text),
139	            ModelFamily::Anthropic,
140	            strict_ruleset(),
141	        )
142	        .unwrap();
143	        assert!(!s.synthesizing);
144	        assert!(s.tool.is_none());
145	        assert!(s.tool_choice.is_none());
146	    }
147	
148	    #[test]
149	    fn none_format_returns_no_synthesis() {
150	        let s = synthesize(None, ModelFamily::Anthropic, strict_ruleset()).unwrap();
151	        assert!(!s.synthesizing);
152	    }
153	
154	    #[test]
155	    fn json_schema_on_anthropic_synthesizes_tool_and_tool_choice() {
