242	/// Translate a core [`ToolChoice`] into a Bedrock [`BedrockToolChoice`].
243	///
244	/// Returns `None` when the family does not support forced tool choice (the
245	/// `tool_choice` field is omitted from the request). `ToolChoice::None` is
246	/// handled before this function is called (it suppresses `toolConfig` entirely).
247	fn translate_tool_choice(tc: &ToolChoice, family: ModelFamily) -> Option<BedrockToolChoice> {
248	    match tc {
249	        ToolChoice::Auto => Some(BedrockToolChoice::Auto(AutoToolChoice::builder().build())),
250	        ToolChoice::Required => {
251	            if !family.supports_forced_tool_choice() {
252	                tracing::debug!(
253	                    target: "paigasus::bedrock::translate",
254	                    ?family,
255	                    "ToolChoice::Required requested but family does not support forced tool choice; omitting",
256	                );
257	                return None;
258	            }
259	            Some(BedrockToolChoice::Any(AnyToolChoice::builder().build()))
260	        }
261	        ToolChoice::None => {
262	            // ToolChoice::None is handled early in build_request; unreachable here.
263	            None
264	        }
265	        ToolChoice::Tool { name } => {
266	            if !family.supports_forced_tool_choice() {
267	                tracing::debug!(
268	                    target: "paigasus::bedrock::translate",
269	                    ?family,
270	                    tool = %name,
271	                    "ToolChoice::Tool requested but family does not support forced tool choice; omitting",
272	                );
273	                return None;
274	            }
275	            match SpecificToolChoice::builder().name(name).build() {
276	                Ok(s) => Some(BedrockToolChoice::Tool(s)),
277	                Err(e) => {
278	                    tracing::warn!(
279	                        target: "paigasus::bedrock::translate",
280	                        err = %e,
281	                        "failed to build SpecificToolChoice; omitting tool_choice",
282	                    );
283	                    None
284	                }
285	            }
286	        }
287	        _ => {
288	            tracing::debug!(
289	                target: "paigasus::bedrock::translate",
290	                "unknown ToolChoice variant; omitting",
291	            );
292	            None
293	        }
294	    }
295	}
