1	//! JSON schema translation rulesets for the Bedrock Converse API.
2	//!
3	//! The primary entry point is [`rewrite_tool_schema`], which transforms a
4	//! JSON Schema value into a Bedrock-compatible form according to the given
5	//! [`Ruleset`].
6	
7	/// Selects the rewrite strategy for tool schemas.
8	///
9	/// Currently the only variant is [`Ruleset::Strict`], which:
10	/// - inlines all `$ref`/`$defs`/`definitions` references,
11	/// - collapses `oneOf`/`anyOf`/`allOf` into a single relaxed object,
12	/// - strips keywords unsupported by the Bedrock Converse API.
13	///
14	/// The `#[non_exhaustive]` attribute allows future variants without a
15	/// breaking change.
16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	#[non_exhaustive]
18	pub enum Ruleset {
19	    /// The Bedrock strict rewrite: inline refs, collapse combinators, strip
20	    /// unsupported keywords. Does **not** add `additionalProperties:false`
21	    /// or promote `required`.
22	    Strict,
23	}
24	
25	impl Ruleset {
26	    /// Return the appropriate [`Ruleset`] for the given [`crate::ModelFamily`].
27	    ///
28	    /// All Bedrock model families currently use [`Ruleset::Strict`].
29	    pub fn for_family(_f: crate::ModelFamily) -> Self {
30	        Ruleset::Strict
31	    }
32	}
33	
34	// ── Constants ────────────────────────────────────────────────────────────────
35	
36	/// Maximum recursion depth before substituting a terminal `{"type":"object"}`.
37	const MAX_DEPTH: usize = 64;
38	
39	/// Keywords stripped from every schema node before returning.
40	const UNSUPPORTED_KEYS: &[&str] = &[
41	    "$schema", "$id", "$anchor", "format", "examples", "default", "$comment",
42	];
43	
44	// ── Public entry point ────────────────────────────────────────────────────────
45	
46	/// Rewrite `schema` into a Bedrock-compatible tool schema using the given
47	/// [`Ruleset`].
48	///
49	/// The transform is **total** (never panics) and **idempotent**
50	/// (`rewrite(rewrite(x)) == rewrite(x)`).
51	///
52	/// # Transform summary (Strict ruleset)
53	/// 1. Inline all `$ref` references from `$defs`/`definitions`.
54	/// 2. Collapse `oneOf`/`anyOf`/`allOf` into one relaxed object.
55	/// 3. Strip unsupported keywords: `$schema`, `$id`, `$anchor`, `format`,
56	///    `examples`, `default`, `$comment`.
57	/// 4. Cycles or nodes exceeding the internal depth limit (64) become `{"type":"object"}`.
58	pub fn rewrite_tool_schema(schema: &serde_json::Value, ruleset: Ruleset) -> serde_json::Value {
59	    match ruleset {
60	        Ruleset::Strict => {
61	            // Extract the top-level $defs / definitions map (if any).
62	            let empty_map = serde_json::Map::new();
63	            let defs: &serde_json::Map<String, serde_json::Value> = schema
64	                .as_object()
65	                .and_then(|o| o.get("$defs").or_else(|| o.get("definitions")))
66	                .and_then(|v| v.as_object())
67	                .unwrap_or(&empty_map);
68	
69	            let mut rewriter = Rewriter {
70	                defs,
71	                chain: Vec::new(),
72	                depth: 0,
73	            };
74	            let mut result = rewriter.rewrite_node(schema);
75	
76	            // Remove $defs / definitions from the root output — they have been
77	            // fully inlined.
78	            if let Some(obj) = result.as_object_mut() {
79	                obj.remove("$defs");
80	                obj.remove("definitions");
81	            }
82	            result
83	        }
84	    }
85	}
86	
87	// ── Rewriter ─────────────────────────────────────────────────────────────────
88	
89	/// Stateful rewriter that carries the definition map and cycle-detection chain.
90	struct Rewriter<'a> {
91	    /// Top-level definitions map extracted from the root schema.
92	    defs: &'a serde_json::Map<String, serde_json::Value>,
93	    /// Stack of definition names currently being expanded (cycle detection).
94	    chain: Vec<String>,
95	    /// Current recursion depth (over-depth guard).
96	    depth: usize,
97	}
98	
99	/// Canonical terminal node returned for cycles and over-depth situations.
100	#[inline]
101	fn terminal_object() -> serde_json::Value {
102	    serde_json::json!({"type": "object"})
103	}
104	
105	impl<'a> Rewriter<'a> {
106	    /// Rewrite a single schema node recursively.
107	    fn rewrite_node(&mut self, node: &serde_json::Value) -> serde_json::Value {
108	        // Guard: over-depth
109	        if self.depth >= MAX_DEPTH {
110	            return terminal_object();
111	        }
112	
113	        let Some(obj) = node.as_object() else {
114	            // Non-object values (arrays, strings, …) pass through unchanged.
115	            return node.clone();
116	        };
117	
118	        // ── 1. $ref handling ─────────────────────────────────────────────────
119	        if let Some(ref_val) = obj.get("$ref") {
120	            return self.handle_ref(ref_val, obj);
121	        }
122	
123	        // ── 2. Combinator handling ───────────────────────────────────────────
124	        for combinator in ["oneOf", "anyOf", "allOf"] {
125	            if let Some(variants_val) = obj.get(combinator) {
126	                if let Some(variants) = variants_val.as_array() {
127	                    return self.collapse_combinator(variants);
128	                }
129	            }
130	        }
131	
132	        // ── 3. Plain object: strip, recurse into children ───────────────────
133	        let mut out = serde_json::Map::new();
134	        for (key, val) in obj {
135	            if UNSUPPORTED_KEYS.contains(&key.as_str()) {
136	                continue;
137	            }
138	            // Skip $defs / definitions — they are handled at the root level.
139	            if key == "$defs" || key == "definitions" {
140	                continue;
141	            }
142	            let new_val = match key.as_str() {
143	                "properties" => self.recurse_properties(val),
144	                "items" => self.recurse_items(val),
145	                "additionalProperties" => {
146	                    if val.is_object() {
147	                        self.depth += 1;
148	                        let v = self.rewrite_node(val);
149	                        self.depth -= 1;
150	                        v
151	                    } else {
152	                        val.clone()
153	                    }
154	                }
155	                _ => val.clone(),
156	            };
157	            out.insert(key.clone(), new_val);
158	        }
159	        serde_json::Value::Object(out)
160	    }
161	
162	    /// Handle a `$ref` keyword.  Sibling keys (after stripping unsupported
163	    /// ones) are merged into the resolved schema (siblings win on collision).
164	    fn handle_ref(
165	        &mut self,
166	        ref_val: &serde_json::Value,
167	        siblings: &serde_json::Map<String, serde_json::Value>,
168	    ) -> serde_json::Value {
169	        let ref_str = match ref_val.as_str() {
170	            Some(s) => s,
171	            None => return terminal_object(),
172	        };
173	
174	        // Resolve the reference target.
175	        let resolved_clone: serde_json::Value = match self.resolve_ref(ref_str) {
176	            Some(v) => v.clone(),
177	            None => return terminal_object(),
178	        };
179	
180	        // Extract the definition name for cycle detection (only for local refs).
181	        let def_name = local_def_name(ref_str).map(|s| s.to_owned());
182	
183	        if let Some(ref name) = def_name {
184	            if self.chain.contains(name) {
185	                // Cycle detected → terminal
186	                return terminal_object();
187	            }
188	            self.chain.push(name.clone());
189	        }
190	
191	        self.depth += 1;
192	        let mut expanded = self.rewrite_node(&resolved_clone);
193	        self.depth -= 1;
194	
195	        if let Some(ref name) = def_name {
196	            self.chain.retain(|n| n != name);
197	        }
198	
199	        // Merge sibling keys (siblings win).  Strip unsupported siblings.
200	        if let Some(exp_obj) = expanded.as_object_mut() {
201	            for (key, val) in siblings {
202	                if key == "$ref" {
203	                    continue;
204	                }
205	                if UNSUPPORTED_KEYS.contains(&key.as_str()) {
206	                    continue;
207	                }
208	                exp_obj.insert(key.clone(), val.clone());
209	            }
210	        }
211	
212	        expanded
213	    }
214	
215	    /// Resolve a `$ref` string against the top-level definitions map.
216	    ///
217	    /// Supports `#/$defs/<name>` and `#/definitions/<name>`.
218	    /// Returns `None` for external / unresolvable refs.
219	    fn resolve_ref(&self, ref_str: &str) -> Option<&serde_json::Value> {
220	        let name = local_def_name(ref_str)?;
221	        self.defs.get(name)
222	    }
223	
224	    /// Collapse a `oneOf`/`anyOf`/`allOf` combinator into one relaxed object.
225	    ///
226	    /// Algorithm:
227	    /// 1. Rewrite each variant (resolving any refs within).
228	    /// 2. Collect variant objects; non-object variants are skipped.
229	    /// 3. Detect a "shared tag key": a property present in **all** variants
230	    ///    whose schema is a `const` string or a single-value `enum` string.
231	    /// 4. Emit `{"type":"string","enum":[tags…]}` for the tag key.
232	    /// 5. Union the remaining properties: if a key appears in multiple variants
233	    ///    and both are object schemas with `properties`, merge their properties
234	    ///    (all optional — do NOT add `required`); otherwise fall back to
235	    ///    `{"type":"object"}`. This ensures variant-1-only payload fields survive.
236	    /// 6. Return `{"type":"object","properties":<union>}` (drop `required` and
237	    ///    `additionalProperties` — the Strict ruleset must not inject these).
238	    ///    If the union is empty, return `{"type":"object"}` with no `properties`.
239	    fn collapse_combinator(&mut self, variants: &[serde_json::Value]) -> serde_json::Value {
240	        // Rewrite each variant first.
241	        let rewritten: Vec<serde_json::Value> = variants
242	            .iter()
243	            .map(|v| {
244	                self.depth += 1;
245	                let r = self.rewrite_node(v);
246	                self.depth -= 1;
247	                r
248	            })
249	            .collect();
250	
251	        // Only consider object variants.
252	        let obj_variants: Vec<&serde_json::Map<String, serde_json::Value>> =
253	            rewritten.iter().filter_map(|v| v.as_object()).collect();
254	
255	        if obj_variants.is_empty() {
256	            return terminal_object();
257	        }
258	
259	        // Collect properties maps from all variants.
260	        let props_maps: Vec<&serde_json::Map<String, serde_json::Value>> = obj_variants
261	            .iter()
262	            .filter_map(|v| v.get("properties").and_then(|p| p.as_object()))
263	            .collect();
264	
265	        // Detect shared tag key.
266	        // A "tag key" is a property present in ALL variants whose schema is a
267	        // `const` string or single-value `enum` string.
268	        let tag_key: Option<(String, Vec<serde_json::Value>)> =
269	            if props_maps.len() == obj_variants.len() {
270	                // All variants have a `properties` map — look for a shared tag.
271	                find_shared_tag(&props_maps)
272	            } else {
273	                None
274	            };
275	
276	        // Build the union of non-tag properties (first-wins on collision).
277	        let mut union_props: serde_json::Map<String, serde_json::Value> = serde_json::Map::new();
278	
279	        if let Some((ref tag_name, ref tag_values)) = tag_key {
280	            // Insert the tag property as an enum of all tag strings.
281	            union_props.insert(
282	                tag_name.clone(),
283	                serde_json::json!({"type": "string", "enum": tag_values}),
284	            );
285	        }
286	
287	        // Union all other properties from every variant (deep-merge object schemas).
288	        for props in &props_maps {
289	            for (key, val) in *props {
290	                if let Some((ref tag_name, _)) = tag_key {
291	                    if key == tag_name {
292	                        continue; // already handled
293	                    }
294	                }
295	                union_props
296	                    .entry(key.clone())
297	                    .and_modify(|existing| {
298	                        *existing = merge_object_schemas(existing, val);
299	                    })
300	                    .or_insert_with(|| val.clone());
301	            }
302	        }
303	
304	        if union_props.is_empty() {
305	            terminal_object()
306	        } else {
307	            serde_json::json!({"type": "object", "properties": union_props})
308	        }
309	    }
310	
311	    /// Recurse into a `properties` object (the value of the `properties` key).
312	    fn recurse_properties(&mut self, val: &serde_json::Value) -> serde_json::Value {
313	        let Some(props) = val.as_object() else {
314	            return val.clone();
315	        };
316	        let mut out = serde_json::Map::new();
317	        for (key, prop_schema) in props {
318	            self.depth += 1;
319	            let rewritten = self.rewrite_node(prop_schema);
320	            self.depth -= 1;
321	            out.insert(key.clone(), rewritten);
322	        }
323	        serde_json::Value::Object(out)
324	    }
325	
326	    /// Recurse into an `items` value (either an object schema or an array of
327	    /// schemas).
328	    fn recurse_items(&mut self, val: &serde_json::Value) -> serde_json::Value {
329	        if val.is_object() {
330	            self.depth += 1;
331	            let r = self.rewrite_node(val);
332	            self.depth -= 1;
333	            r
334	        } else if let Some(arr) = val.as_array() {
335	            let rewritten: Vec<serde_json::Value> = arr
336	                .iter()
337	                .map(|item| {
338	                    self.depth += 1;
339	                    let r = self.rewrite_node(item);
340	                    self.depth -= 1;
341	                    r
342	                })
343	                .collect();
344	            serde_json::Value::Array(rewritten)
345	        } else {
346	            val.clone()
347	        }
348	    }
349	}
350	
351	// ── Helpers ───────────────────────────────────────────────────────────────────
352	
353	/// Merge two object schemas for the same shared payload key.
354	///
355	/// If both schemas are objects with `properties`, union their properties (all
356	/// keys, all optional — no `required` added). If either schema is non-object
357	/// or cannot be merged, fall back to `{"type":"object"}` (permissive).
358	fn merge_object_schemas(a: &serde_json::Value, b: &serde_json::Value) -> serde_json::Value {
359	    let (Some(a_obj), Some(b_obj)) = (a.as_object(), b.as_object()) else {
360	        return serde_json::json!({"type": "object"});
361	    };
362	
363	    let a_props = a_obj.get("properties").and_then(|p| p.as_object());
364	    let b_props = b_obj.get("properties").and_then(|p| p.as_object());
365	
366	    match (a_props, b_props) {
367	        (Some(ap), Some(bp)) => {
368	            let mut merged = ap.clone();
369	            for (key, val) in bp {
370	                merged.entry(key.clone()).or_insert_with(|| val.clone());
371	            }
372	            serde_json::json!({"type": "object", "properties": merged})
373	        }
374	        _ => {
375	            // At least one schema has no properties; fall back to permissive object.
376	            serde_json::json!({"type": "object"})
377	        }
378	    }
379	}
380	
381	/// Extract the definition name from a local `$ref` string.
382	///
383	/// Handles `#/$defs/<name>` and `#/definitions/<name>`.
384	/// Returns `None` for anything else (external / unsupported).
385	fn local_def_name(ref_str: &str) -> Option<&str> {
386	    if let Some(name) = ref_str.strip_prefix("#/$defs/") {
387	        return Some(name);
388	    }
389	    if let Some(name) = ref_str.strip_prefix("#/definitions/") {
390	        return Some(name);
391	    }
392	    None
393	}
394	
395	/// Detect a shared "tag" key across all variant property maps.
396	///
397	/// A property is a shared tag if:
398	/// - It is present in **every** variant's `properties` map.
399	/// - Its schema in every variant has either `"const": <string>` or
400	///   `"enum": [<single-string>]`.
401	///
402	/// Returns `Some((tag_key, [tag_values…]))` where `tag_values` preserves
403	/// variant order and contains no duplicates (first occurrence wins).
404	fn find_shared_tag(
405	    props_maps: &[&serde_json::Map<String, serde_json::Value>],
406	) -> Option<(String, Vec<serde_json::Value>)> {
407	    if props_maps.is_empty() {
408	        return None;
409	    }
410	
411	    // Candidate keys: all keys in the first variant.
412	    let candidates: Vec<&str> = props_maps[0].keys().map(|k| k.as_str()).collect();
413	
414	    for candidate in candidates {
415	        // Check if the candidate is a tag key in all variants.
416	        let mut tag_values: Vec<serde_json::Value> = Vec::new();
417	        let mut all_match = true;
418	
419	        for props in props_maps {
420	            match props.get(candidate) {
421	                Some(schema) => {
422	                    if let Some(tag_val) = extract_const_string(schema) {
423	                        if !tag_values.contains(&tag_val) {
424	                            tag_values.push(tag_val);
425	                        }
426	                    } else {
427	                        all_match = false;
428	                        break;
429	                    }
430	                }
431	                None => {
432	                    all_match = false;
433	                    break;
434	                }
435	            }
436	        }
437	
438	        if all_match && !tag_values.is_empty() {
439	            return Some((candidate.to_owned(), tag_values));
440	        }
441	    }
442	
443	    None
444	}
445	
446	/// Extract the string value from a `const` or single-element `enum` schema.
447	///
448	/// Returns `None` if the schema is not a string-valued const/enum.
449	fn extract_const_string(schema: &serde_json::Value) -> Option<serde_json::Value> {
450	    let obj = schema.as_object()?;
451	
452	    // {"const": "SomeString"}
453	    if let Some(const_val) = obj.get("const") {
454	        if const_val.is_string() {
455	            return Some(const_val.clone());
456	        }
457	    }
458	
459	    // {"enum": ["SomeString"]}
460	    if let Some(enum_val) = obj.get("enum") {
461	        if let Some(arr) = enum_val.as_array() {
462	            if arr.len() == 1 && arr[0].is_string() {
463	                return Some(arr[0].clone());
464	            }
465	        }
466	    }
467	
468	    None
469	}
470	
471	// ── Unit tests ────────────────────────────────────────────────────────────────
472	
473	#[cfg(test)]
474	mod tests {
475	    use super::*;
476	    use serde_json::json;
477	
478	    fn strict(v: serde_json::Value) -> serde_json::Value {
479	        rewrite_tool_schema(&v, Ruleset::Strict)
480	    }
481	
482	    fn has_key_anywhere(v: &serde_json::Value, key: &str) -> bool {
483	        match v {
484	            serde_json::Value::Object(m) => {
485	                m.contains_key(key) || m.values().any(|c| has_key_anywhere(c, key))
486	            }
487	            serde_json::Value::Array(a) => a.iter().any(|c| has_key_anywhere(c, key)),
488	            _ => false,
489	        }
490	    }
491	
492	    #[test]
493	    fn inlines_defs_ref() {
494	        let input = json!({
495	            "type":"object",
496	            "properties": {"inner": {"$ref":"#/$defs/Inner"}},
497	            "$defs": {"Inner": {"type":"object","properties":{"x":{"type":"string"}}}}
498	        });
499	        let out = strict(input);
500	        assert!(!has_key_anywhere(&out, "$ref"));
501	        assert!(!has_key_anywhere(&out, "$defs"));
502	        assert_eq!(
503	            out["properties"]["inner"]["properties"]["x"]["type"],
504	            json!("string")
505	        );
506	    }
507	
508	    #[test]
509	    fn inlines_ref_inside_items_and_chained_refs() {
510	        let input = json!({
511	            "type":"object",
512	            "properties": {"list": {"type":"array","items":{"$ref":"#/$defs/A"}}},
513	            "$defs": {"A": {"type":"object","properties":{"b":{"$ref":"#/$defs/B"}}},
514	                      "B": {"type":"object","properties":{"v":{"type":"integer"}}}}
515	        });
516	        let out = strict(input);
517	        assert!(!has_key_anywhere(&out, "$ref"));
518	        assert_eq!(
519	            out["properties"]["list"]["items"]["properties"]["b"]["properties"]["v"]["type"],
520	            json!("integer")
521	        );
522	    }
523	
524	    #[test]
525	    fn ref_with_sibling_keywords_merges() {
526	        let input = json!({
527	            "type":"object",
528	            "properties": {"p": {"$ref":"#/$defs/T","description":"doc"}},
529	            "$defs": {"T": {"type":"string"}}
530	        });
531	        let out = strict(input);
532	        assert_eq!(out["properties"]["p"]["type"], json!("string"));
533	        assert_eq!(out["properties"]["p"]["description"], json!("doc"));
534	    }
535	
536	    #[test]
537	    fn unresolvable_external_ref_becomes_permissive_object() {
538	        let input = json!({"type":"object","properties":{"p":{"$ref":"https://example/x"}}});
539	        let out = strict(input);
540	        assert!(!has_key_anywhere(&out, "$ref"));
541	        assert_eq!(out["properties"]["p"], json!({"type":"object"}));
542	    }
543	
544	    #[test]
545	    fn recursive_type_terminates_and_is_idempotent() {
546	        let input = json!({
547	            "type":"object",
548	            "properties":{"child":{"$ref":"#/$defs/Node"}},
549	            "$defs":{"Node":{"type":"object","properties":{"child":{"$ref":"#/$defs/Node"}}}}
550	        });
551	        let once = strict(input.clone());
552	        let twice = rewrite_tool_schema(&once, Ruleset::Strict);
553	        assert!(!has_key_anywhere(&once, "$ref"));
554	        assert_eq!(once, twice, "rewrite must be idempotent on recursive types");
555	    }
556	
557	    #[test]
558	    fn collapses_tagged_enum_oneof() {
559	        // serde adjacently-tagged: {"t": "A"|"B", "c": payload}
560	        let input = json!({
561	            "oneOf": [
562	                {"type":"object","properties":{"t":{"const":"A"},"c":{"type":"object","properties":{"a":{"type":"string"}}}}},
563	                {"type":"object","properties":{"t":{"const":"B"},"c":{"type":"object","properties":{"b":{"type":"integer"}}}}}
564	            ]
565	        });
566	        let out = strict(input);
567	        assert!(!has_key_anywhere(&out, "oneOf"));
568	        assert!(!has_key_anywhere(&out, "anyOf"));
569	        assert!(!has_key_anywhere(&out, "allOf"));
570	        assert_eq!(out["type"], json!("object"));
571	        // tag became an enum of variant tags; properties non-empty
572	        assert_eq!(out["properties"]["t"]["enum"], json!(["A", "B"]));
573	        assert!(!out["properties"].as_object().unwrap().is_empty());
574	        assert!(
575	            out.get("required").is_none(),
576	            "Strict must not promote required"
577	        );
578	        assert!(
579	            out.get("additionalProperties").is_none(),
580	            "Strict must not inject additionalProperties"
581	        );
582	    }
583	
584	    #[test]
585	    fn tagged_enum_variant1_only_field_survives_in_union() {
586	        // Verify that a field present ONLY in variant 1 (not variant 0) appears
587	        // in the merged output.
588	        let input = json!({
589	            "oneOf": [
590	                {"type":"object","properties":{"t":{"const":"A"},"payload":{"type":"object","properties":{"x":{"type":"string"}}}}},
591	                {"type":"object","properties":{"t":{"const":"B"},"payload":{"type":"object","properties":{"y":{"type":"integer"}}}}}
592	            ]
593	        });
594	        let out = strict(input);
595	        // "x" is variant 0's field, "y" is variant 1's field — both must survive.
596	        assert!(
597	            out["properties"]["payload"]["properties"]
598	                .get("x")
599	                .is_some(),
600	            "variant 0 field 'x' must survive"
601	        );
602	        assert!(
603	            out["properties"]["payload"]["properties"]
604	                .get("y")
605	                .is_some(),
606	            "variant 1 field 'y' must survive in merged payload"
607	        );
608	    }
609	
610	    #[test]
611	    fn strips_unsupported_keywords() {
612	        let input = json!({"type":"object","$schema":"...","$id":"x","format":"email","examples":[1],
613	            "properties":{"p":{"type":"string","format":"uri"}}});
614	        let out = strict(input);
615	        for k in ["$schema", "$id", "format", "examples"] {
616	            assert!(!has_key_anywhere(&out, k), "{k} not stripped");
617	        }
618	        assert_eq!(out["properties"]["p"]["type"], json!("string"));
619	    }
620	}
