/// Fold one turn's final usage into the running cross-turn total (SMA-402).
/// `TokenUsage` is `Copy`; returns the new cumulative total.
fn accumulate(prior: TokenUsage, this_turn: TokenUsage) -> TokenUsage {
    let mut total = prior;
