1	//! Snapshot integration tests for the Bedrock tool-schema rewriter.
2	//!
3	//! Run with:
4	//! ```text
5	//! INSTA_UPDATE=always cargo test -p paigasus-helikon-providers-bedrock --test schema_rewriter
6	//! ```
7	//! or after new test additions:
8	//! ```text
9	//! cargo insta test --accept
10	//! ```
11	
12	use paigasus_helikon_providers_bedrock::{rewrite_tool_schema, Ruleset};
13	use serde_json::json;
14	
15	/// A realistic schemars-style adjacently-tagged enum schema (as generated by
16	/// `schemars::JsonSchema` with `#[serde(tag = "type", content = "payload")]`).
17	///
18	/// ```json
19	/// { "oneOf": [ VariantA, VariantB, VariantC ] }
20	/// ```
21	///
